def resolve_model(model: str) -> str:
    m = model.lower().strip()
    if m in ALIASES:
        return ALIASES[m]
    if m in MODELS:
        return m
    if MODELS:
        first = next(iter(MODELS))
        logger.warning(f"resolve_model: '{model}' not found in {len(MODELS)} models, fallback → '{first}'")
        return first
    return model


